(() => {
  const world = [{"id":"alpha","name":"Alpha Metrics","version":"1.8.2","publisher":"Fixture Labs","category":"Monitoring","summary":"Dashboards and data sources for the alpha service.","state":"running"},{"id":"beta","name":"Beta Registry","version":"0.24.0","publisher":"Fixture Labs","category":"Containers","summary":"Browse repositories, tags and images in the beta registry.","state":"running"},{"id":"delta","name":"Delta Vault","version":"1.0.3","publisher":"Delta Systems","category":"Security","summary":"Secrets, leases and policies for a delta server.","state":"disabled"},{"id":"epsilon","name":"Epsilon Mesh","version":"0.4.1","publisher":"Epsilon Works","category":"Networking","summary":"Services, routes and traffic policy for an epsilon mesh.","state":"starting"},{"id":"gamma","name":"Gamma Deploy","version":"2.3.0","publisher":"Gamma Community","category":"DevOps","summary":"Rollouts, environments and the release history of a gamma project.","state":"failed"},{"id":"zeta","name":"Zeta Jobs","version":"3.1.0","publisher":"Fixture Labs","category":"DevOps","summary":"Scheduled jobs, their runs and their outcomes.","state":"running"}];
  // 1. Every plugin of the mock's default world is uninstalled.
  for (const record of Shell.pluginData.list({ installed: true })) Shell.pluginData.set(record.id, { installed: false });
  // 2. The neutral plugins are installed, as records of the world and as marketplace plugins (`market: true`: the detail then has the Versions and Changelog tabs and the downloads of the facts line).
  //    The flush runs the page's own sync at once: it registers a stub plugin for each record, so the health below has a plugin to be written for, and adopts the record's identity (the sync that the writes below
  //    cause adopts `market`).
  for (const plugin of world) {
    Shell.pluginData.set(plugin.id, { name: plugin.name, publisher: plugin.publisher, category: plugin.category, summary: plugin.summary, icon: "LuPuzzle", mark: plugin.name.slice(0, 2).toUpperCase(),
      installed: true, version: plugin.version, source: 'marketplace', enabled: plugin.state !== 'disabled', market: true, official: false, verified: false, installedAt: 1791028800000, caps: ["net.endpoint","secrets.store","clipboard"] });
  }
  Shell.flush();
  // 3. Health: the failed plugin's service has failed, the starting plugin's service is starting (the disabled one is enabled: false above).
  for (const plugin of world) {
    if (plugin.state === 'failed') Shell.plugins.report(plugin.id, { service: 'failed', reason: "The plugin process stopped unexpectedly, so its pages can't load data.", retries: { attempt: 0, max: 5, delays: [3600, 3600, 3600, 3600, 3600], persist: true } });
    if (plugin.state === 'starting') Shell.plugins.report(plugin.id, { service: 'starting' });
  }
  // 4. The page's own state selects the plugin it shows the detail of ('' selects none); the page is then opened in the current tab, so its first render already shows that plugin.
  Shell.update(['pluginsPage', 'ui'], { selected: "<selected>" });
  Shell.flush();
  Shell.tabs.open({ plugin: 'host', route: { page: 'host/plugins' } }, { how: 'here' });
})()
